<script setup lang="ts">
import { onLoad, onShow } from '@dcloudio/uni-app'
import { ref } from 'vue'
import PageLoading from '../../components/PageLoading.vue'
import StoreSelector from '../../components/StoreSelector.vue'
import { request } from '../../utils/api'
import { businessDate, currentStoreId, errorMessage } from '../../utils/session'

const report = ref<any>(null)
const canGeneratePoster = ref(false)
const loadingPage = ref(true)
const message = ref('')
const date = ref(businessDate())
const storeId = ref<number | null>(currentStoreId())
const show = (value: number | null | undefined) => value == null ? '?' : String(value)
const money = (value: number | null | undefined) => value == null ? '?' : Number(value).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
const percent = (value: number | null | undefined) => value == null ? '?' : `${(value * 100).toFixed(1)}%`

onLoad((options) => {
  if (typeof options?.date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(options.date)) date.value = options.date
  const requestedStoreId = Number(options?.storeId)
  if (Number.isInteger(requestedStoreId) && requestedStoreId > 0) storeId.value = requestedStoreId
})
onShow(() => { if (storeId.value) void loadReport() })

async function loadReport() {
  if (!storeId.value) return
  loadingPage.value = true; message.value = ''
  try {
    const access = await request<{ stores?: Array<{ id: number; permissionCodes: string[] }> }>('/api/hr/current-access')
    const permissions = access.stores?.find((store) => store.id === storeId.value)?.permissionCodes ?? []
    const reportPermission = date.value < businessDate() ? 'HR_HISTORY_REPORT_READ' : 'HR_DAILY_REPORT_READ'
    canGeneratePoster.value = permissions.includes(reportPermission) && permissions.includes('HR_DAILY_REPORT_POSTER')
    report.value = await request(`/api/reports/daily?storeId=${storeId.value}&date=${date.value}`)
  }
  catch (error) { message.value = errorMessage(error) }
  finally { loadingPage.value = false }
}

const openPoster = () => uni.navigateTo({ url: `/pages/report-poster/index?storeId=${storeId.value}&date=${date.value}` })
</script>
<template><view class="page report-page"><PageLoading v-if="loadingPage" /><view class="share-bar"><view class="share-context"><view><text class="share-title">日报简报</text><text class="share-desc">生成图片后可直接转发</text></view><StoreSelector v-model="storeId" source="hr" permission="HR_DAILY_REPORT_READ" @ready="loadReport" @change="loadReport" /></view><button v-if="report && canGeneratePoster" class="poster-button" @click="openPoster">生成简报图片</button></view><view v-if="message" class="card"><text class="section-title">暂时无法生成日报</text><text class="section-subtitle">{{ message }}</text></view><template v-if="report"><view class="report-hero"><text class="report-store">{{ report.store?.name || '米熊门店' }}</text><text class="report-date">{{ date }} · 经营日报</text><view class="report-main"><text>总销售额</text><text><small>¥</small>{{ money(report.sales?.total?.amount) }}</text></view><view class="report-quick"><view><text>总入客</text><strong>{{ show(report.sales?.total?.customers) }}</strong></view><view><text>客单价</text><strong>¥{{ money(report.sales?.total?.avgOrderValue) }}</strong></view></view></view><view v-if="!report.status?.complete" class="incomplete"><text>!</text>日报数据尚未完整，部分指标可能为空</view><view class="card"><text class="section-title">销售渠道</text><view v-for="item in [{ name: '堂食', data: report.sales?.dineIn, icon: '店' }, { name: '外卖', data: report.sales?.delivery, icon: '外' }]" :key="item.name" class="channel-row"><view class="channel-icon">{{ item.icon }}</view><view class="channel-info"><text>{{ item.name }}</text><text>{{ show(item.data?.customers) }} 人 · 客单 ¥{{ money(item.data?.avgOrderValue) }}</text></view><view class="channel-number"><strong>¥{{ money(item.data?.amount) }}</strong><text>{{ percent(item.data?.ratio) }}</text></view></view></view><view class="card"><text class="section-title">营业时段</text><view v-for="item in report.periods" :key="item.code" class="data-row"><view><text>{{ item.name }}</text><text>{{ show(item.customers) }} 人 · 客单 ¥{{ money(item.avgOrderValue) }}</text></view><strong>¥{{ money(item.amount) }}</strong></view></view><view class="two-column"><view class="card mini-card"><text class="mini-label">电效率</text><text class="mini-value">{{ show(report.energy?.powerEfficiency) }}</text><text class="mini-unit">元 / 度</text></view><view class="card mini-card"><text class="mini-label">工时收入</text><text class="mini-value">{{ show(report.labor?.salesPerHour) }}</text><text class="mini-unit">元 / 小时</text></view></view><view class="card"><text class="section-title">团购统计</text><view class="data-row total-row"><view><text>团购总计</text><text>{{ show(report.groupBuy?.total?.customers) }} 人</text></view><strong>¥{{ money(report.groupBuy?.total?.amount) }}</strong></view><view v-for="item in report.groupBuy?.platforms" :key="item.code" class="data-row compact"><text>{{ item.name }}</text><text>¥{{ money(item.amount) }} · {{ show(item.customers) }} 人</text></view></view><view class="card"><text class="section-title">菜品结构</text><view v-for="item in report.categorySales" :key="item.categoryId" class="data-row compact"><text>{{ item.categoryName }}</text><strong>{{ show(item.quantity) }} <small>份</small></strong></view></view><view class="card"><text class="section-title">运营指标</text><view v-for="item in [{name:'加点人数',value:report.operations?.addonCustomers,unit:'人'},{name:'千人加点',value:report.operations?.addonPerThousand,unit:''},{name:'套餐人数',value:report.operations?.comboCustomers,unit:'人'},{name:'千人套餐',value:report.operations?.comboPerThousand,unit:''}]" :key="item.name" class="data-row compact"><text>{{ item.name }}</text><strong>{{ show(item.value) }} <small>{{ item.unit }}</small></strong></view></view><view class="card"><text class="section-title">菜品销售明细</text><view v-for="category in report.productSales" :key="category.categoryId" class="product-section"><text class="product-category">{{ category.categoryName }}</text><view v-for="item in category.items" :key="item.productId" class="product-row"><text class="rank">{{ item.rank }}</text><text class="product-name">{{ item.productName }}</text><strong>{{ show(item.quantity) }}</strong></view></view></view></template></view></template>
